    def _impl_v9(cls, inputs, attr, params):
        in_checked_type = infer_type(inputs[0]).checked_type
        in_dtype = in_checked_type.dtype
        in_shape = list(get_const_tuple(in_checked_type.shape))
        dtype = attr.get("dtype", None)
        if dtype is None:
            dtype = in_dtype
