class MaxHeap(object):

    def __init__(self):
        self._data = []
        self._count = len(self._data)

    def size(self):
        return self._count

    def isEmpty(self):
        return self._count == 0

    def add(self, item):
        # 插入元素入堆
        self._data.append(item)
        self._count += 1
        self._shiftup(self._count - 1)

    def pop(self):
        # 出堆
        if self._count > 0:
            ret = self._data[0]
            self._data[0] = self._data[self._count - 1]
            self._count -= 1
            self._shiftDown(0)
            return ret

    def getTOP(self):
        if self._count > 0:
            return self._data[0]

    def _shiftup(self, index):
        # 上移self._data[index]，以使它不大于父节点
        parent = (index - 1) >> 1
        while index > 0 and self._data[parent] < self._data[index]:
            # swap
            self._data[parent], self._data[index] = self._data[index], self._data[parent]
            index = parent
            parent = (index - 1) >> 1

    def _shiftDown(self, index):
        # 上移self._data[index]，以使它不小于子节点
        j = (index << 1) + 1
        while j < self._count:
            # 有子节点
            if j + 1 < self._count and self._data[j + 1] > self._data[j]:
                # 有右子节点，并且右子节点较大
                j += 1
            if self._data[index] >= self._data[j]:
                # 堆的索引位置已经大于两个子节点，不需要交换了
                break
            self._data[index], self._data[j] = self._data[j], self._data[index]
            index = j
            j = (index << 1) + 1

    def __repr__(self):
        return sorted(self._data, reverse=True)


class MyQueue:

    def __init__(self):
        """
        Initialize your data structure here.
        """
        self.queue = []

    def push(self, x: int) -> None:
        """
        Push element x to the back of queue.
        """
        self.queue.append(x)

    def pop(self) -> int:
        """
        Removes the element from in front of queue and returns that element.
        """
        if self.queue.__len__() > 0:
            return None
        return self.queue.pop(0)

    def peek(self) -> int:
        """
        Get the front element.
        """
        if self.queue.__len__() > 0:
            return None
        return self.queue[0]

    def empty(self) -> bool:
        """
        Returns whether the queue is empty.
        """
        return self.queue.empty()


class MyStack:

    def __init__(self):
        """
        Initialize your data structure here.
        """
        self.queue = []
        self.len = 0

    def push(self, x: int) -> None:
        """
        Push element x onto stack.
        """
        self.queue.insert(self.len, x)
        self.len += 1

    def pop(self) -> int:
        """
        Removes the element on top of the stack and returns that element.
        """
        self.len -= 1
        return self.queue.pop()

    def top(self) -> int:
        """
        Get the top element.
        """
        return self.queue[-1]

    def empty(self) -> bool:
        """
        Returns whether the stack is empty.
        """
        return self.len == 0


class WordDictionary(object):
    '''
    词典的搜索
    '''

    def __init__(self):
        """
        Initialize your data structure here.
        """
        self.dictionary = collections.defaultdict(set)
        self.search_d = collections.defaultdict(bool)

    def addWord(self, word):
        """
        Adds a word into the data structure.
        :type word: str
        :rtype: None
        """
        if not word:
            return
        indexs = [word[0], '.']
        for index in indexs:
            self.dictionary[index].add(word)

        self.search_d.clear()

    def check(self, key, word):
        if len(self.dictionary[key]) == 0:
            return False
        for w in self.dictionary[key]:
            if len(w) != len(word):
                continue
            flag = 0
            for i in range(len(w)):
                if word[i] == '.':
                    continue
                else:
                    if w[i] != word[i]:
                        flag = 1
                        break
            if flag == 0:
                self.search_d[word] = True
                return True
        self.search_d[word] = False
        return False

    def cache(self, search_word):
        '''
        对完成搜索的word直接进行缓存
        :param search_word:
        :return:
        '''
        if search_word in self.search_d.keys():
            return self.search_d[search_word]

        return None

    def search(self, word):
        """
        Returns if the word is in the data structure.
        A word could contain the dot character '.' to represent any one letter.
        :type word: str
        :rtype: bool
        """
        if not word:
            return

        if self.cache(word) is not None:
            print('已进行搜索：', word)
            return self.search_d[word]

        if word.startswith('.'):
            return self.check('.', word)
        else:
            return self.check(word[0], word)


class Trie(object):

    def __init__(self):
        """
        Initialize your data structure here.
        """
        self.trie = collections.defaultdict(set)

    def insert(self, word):
        """
        Inserts a word into the trie.
        :type word: str
        :rtype: None
        """
        if len(word) == 0:
            return
        for i in range(len(word)):
            ch = word[0:i + 1]
            self.trie[ch].add(word)

    def search(self, word):
        """
        Returns if the word is in the trie.
        :type word: str
        :rtype: bool
        """
        return word in self.trie[word]

    def startsWith(self, prefix):
        """
        Returns if there is any word in the trie that starts with the given prefix.
        :type prefix: str
        :rtype: bool
        """
        return len(self.trie[prefix]) > 0


class LRUCache:
    # Your LRUCache object will be instantiated and called as such:
    # obj = LRUCache(capacity)
    # param_1 = obj.get(key)
    # obj.put(key,value)

    def __init__(self, capacity: int):
        self.LRUkeyslist = list()
        self.LRUdict = dict()
        self.capacity = capacity

    def get(self, key: int) -> int:
        if key in self.LRUdict.keys():
            # 取一次key，使用一次，将该健对更新到最近使用，即将该key位置改为list的最后
            self.LRUkeyslist.remove(key)
            self.LRUkeyslist.append(key)
            return self.LRUdict[key]
        else:
            return -1

    def put(self, key: int, value: int) -> None:
        if key not in self.LRUdict.keys():
            # key 不再字典中，则进行插入
            if self.LRUkeyslist.__len__() == self.capacity:
                # 字典满了，删除队列第一个key，同时删除dict中对应键对
                k = self.LRUkeyslist[0]
                del self.LRUkeyslist[0]
                self.LRUdict.pop(k)
            # 随后将键对插入到队列最后,同时更新字典
            self.LRUdict.update({key: value})
            self.LRUkeyslist.append(key)
        else:
            # 设置新值也需将该键对移动到最后
            self.LRUdict[key] = value
            self.LRUkeyslist.remove(key)
            self.LRUkeyslist.append(key)


class LRUCache:
    # Your LRUCache object will be instantiated and called as such:
    # obj = LRUCache(capacity)
    # param_1 = obj.get(key)
    # obj.put(key,value)

    def __init__(self, capacity: int):
        self.LRUdict = collections.OrderedDict()
        self.capacity = capacity

    def get(self, key: int) -> int:
        if key in self.LRUdict.keys():
            # 取一次key，使用一次，将该健对更新到最近使用，即将该key位置改为list的最后
            self.LRUdict.move_to_end(key)
            return self.LRUdict[key]
        else:
            return -1

    def put(self, key: int, value: int) -> None:
        if key not in self.LRUdict.keys():
            # key 不再字典中，则进行插入
            if len(self.LRUdict) == self.capacity:
                # 字典满了，删除队列第一个key，同时删除dict中对应键对
                self.LRUdict.popitem(False)
            self.LRUdict.update({key: value})

        else:
