def BuildTree(layer: list, mid: list):
    # 层次遍历和中序遍历建树
    if mid == []:
        return None
    else:
        i = 0
        while layer[i] not in mid:
            i += 1
        root_val = layer[i]
        layer.remove(root_val)
        root_index = mid.index(root_val)
        root = TreeNode(root_val, BuildTree(
            layer, mid[0:root_index]), BuildTree(layer, mid[root_index + 1:]))
        return root


