def Time(name='FUNC', n=1):
    def decorate(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            start = time.time()
            for _ in range(n - 1):
                func(*args, **kwargs)
            result = func(*args, **kwargs)
            print('\n函数: {name:>10}\nargs: {args}\n运行 {n}次\n需要时间: {time}\n'.format(
                name=func.__name__, n=n, args=args, time=time.time() - start))
            return result

        return wrapper

    return decorate


class MinStack:

