    def push(self, x: int) -> None:
        if self.stack:
            self.stack.append(x)
            if x < self.stack[self.min]:
                self.min = len(self.stack) - 1
        else:
            self.stack.append(x)
            self.min = 0

    def pop(self) -> None:
        return self.stack.pop()

    def top(self) -> int:
        return self.stack[-1]

    def getMin(self) -> int:
        return self.stack[self.min]


