    def maxPathSum(self, root: TreeNode) -> int:
        nonroot = root.val

        # 124.
        def dfs(root: TreeNode) -> int:
            nonlocal nonroot
            if not root:
                return float('-inf')
            else:
                left = dfs(root.left)
                right = dfs(root.right)
                mid = root.val
                nonroot = max(nonroot, left + right + mid, left, right)
                return max(mid, left + mid, right + mid)

        return max(dfs(root), nonroot)

