    def minScoreTriangulation(self, A: list) -> int:
        # 这个方法以边卫递归基础,
        # 反而以顶点为循环点
        # 边加点的形式形成动态表格规划
        table = [[-1 for _ in range(len(A))] for _ in range(len(A))]

        def recusion(x=0, y=len(A) - 1, A: list = A):
            if y - x <= 1:
                return 0
            if table[x][y] != -1:
                return table[x][y]
            else:
                m = float('inf')
                for i in range(x + 1, y):
                    m = min(m, recusion(x, i, A) +
                            recusion(i, y, A) + A[x] * A[y] * A[i])
                table[x][y] = m
                return m

        return recusion()

