    def insertionSortList(self, head: ListNode) -> ListNode:
        # 链表插入排序
        if head == None or head.next == None:
            return head
        p, q = head, head.next

        while q:
            if q.val < p.val:
                l, r = None, head
                while r != q:
                    if r.val > q.val:
                        # 插入到头节点的前面
                        if l == None:
                            p.next = q.next
                            q.next = r
                            head = q
                        else:
                            # 插入到非头结点前
                            p.next = q.next
                            l.next = q
                            q.next = r
                        break
                    r, l = r.next, r
                q = p.next
            else:
                p, q = q, q.next
        return head

