            psf = []
            for i in range(2, int(math.sqrt(n)) + 1):
                if Isprime(i):
                    p = findPow(i, n)
                    if p >= 0:
                        psf.append(i)

                    n -= pow(i, p)
                    if len(psf) >= 3:
                        break
            return psf

