    def Levelorder(self, root, ltr=True):
        # root 树根
        # 层次遍历,
        # stack 存储当前遍历节点， p 存储下一层遍历结点
        if not root:
            return []
        stack, p = [], []

        stack.append(root)
        while stack:
            if not ltr:
                ptr = stack.pop()
            else:
                ptr = stack[0]
                del stack[0]
            yield (ptr.val)
            if ptr.left:
                p.append(ptr.left)
            if ptr.right:
                p.append(ptr.right)
            if stack == []:
                p, stack = stack, p

    def rightSideView(self, root):
