        stack, p = [], []
        result = []
        stack.append(root)
        result.append(root.val)
        while stack:

            ptr = stack[0]
            del stack[0]
            if ptr.left:
                p.append(ptr.left)
            if ptr.right:
                p.append(ptr.right)
            if stack == []:

                if p:
                    result.append(p[-1].val)
                p, stack = stack, p

        return result

    def numIslands(self, grid):
        """
        :type grid: List[List[str]]
        :rtype: int
        """

        # 使用深/广度优先 D/BFS

        def DFS(x, y):
            if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]):
                return
            else:
                if grid[x][y] != '0':
                    grid[x][y] = '0'
                    DFS(x - 1, y)
                    DFS(x, y + 1)
                    DFS(x + 1, y)
                    DFS(x, y - 1)

        count = 0

        for x in range(len(grid)):
            for y in range(len(grid[0])):
                if grid[x][y] == '1':
                    count += 1
                    DFS(x, y)

        return count

