            # 分解数字
            numlist = []

            while n > 0:
                numlist.append(n % 10)
                n //= 10

            return numlist

        while n != 1:
            numdict[n] += 1
            if numdict[n] > 1:
                return False

            nl = decomposeNum(n)
            n = 0
            for i in nl:
