    def reverseList(self, head):
        """
        :type head: ListNode
        :rtype: ListNode
        """

        pre, ptr = None, head
        while ptr:
            if pre == None:

                pre = ptr
                ptr = ptr.next
                pre.next = None
                if ptr == None:
                    return pre
            else:
                if ptr.next == None:
                    ptr.next = pre
                    return ptr
                else:
                    temp = ptr.next
                    ptr.next = pre
                    pre = ptr
                    ptr = temp

        return None

