    @Time(n=1)
    def minSubArrayLen1(self, s, nums):
        """
        找数序找到何为s的最小连续数序的长度
        :type s: int 目标
        :type nums: List[int] 数序
        :rtype: int
        """
        if sum(nums) < s:
            return 0

        if s in nums:
            return 1

        dp = [0 for _ in range(nums.__len__())]
        minlen = len(nums)

        for i in range(len(nums)):
            for j in range(i, -1, -1):
                if i == j:
                    dp[i] = nums[i]
                else:
                    dp[j] = nums[i] + dp[j]
                if dp[j] >= s:
                    if i - j + 1 < minlen:
                        minlen = i - j + 1

                    break
        return minlen

    @Time(n=1)
    def minSubArrayLen2(self, s, nums):
        '''
            设置滑块向右移动
        :param s:
        :param nums:
        :return:
        '''
        n = sum(nums)
        if s > n: return 0
        if s == n: return len(nums)

        left, right = 0, 1
        minlen = len(nums)
        temp = nums[left]
        temp -= nums[right - 1]

        while right <= len(nums):
            temp += nums[right - 1]
            if right < len(nums):
                while temp + nums[right] <= s:
                    temp = temp + nums[right]
                    right += 1

            while temp - nums[left] >= s:
                temp = temp - nums[left]
                left += 1

            if right - left < minlen:
                minlen = right - left

            right += 1

        return minlen

