        """
        :type node: ListNode
        :rtype: void Do not return anything, modify node in-place instead.
        """
        pre, ptr = None, head

        if not ptr: return None
        if ptr.val == node.val: return head.next
        while ptr:
            if ptr.val == node.val:
                pre.next = ptr.next
                break
            else:
                pre, ptr = ptr, ptr.next
        return head

