    def calculate2(self, s: str) -> int:
        # 无括号的加减乘除

        def cal(fs, ns):
            if fs[-1] == '-':
                ns.append(-1 * (ns.pop() - ns.pop()))
            elif fs[-1] == '*':
                ns.append(ns.pop() * ns.pop())
            elif fs[-1] == '/':
                b, a = ns.pop(), ns.pop()
                ns.append(a // b)
            else:
                ns.append(ns.pop() + ns.pop())
            fs.pop()

        s = s.replace(' ', '') + '+0'
        pre, ns, fs = 0, [], []  # 运算符记位+1 ，数字栈， 符号栈

        for i in range(len(s)):

            if s[i] in ['+', '-']:
                ns.append(int(s[pre:i]))
                while ns.__len__() >= 2 and fs.__len__() >= 1:
                    cal(fs, ns)
                fs.append(s[i])
                pre = i + 1
            elif s[i] in ['*', '/']:
                ns.append(int(s[pre:i]))
                while ns.__len__() >= 2 and fs.__len__() >= 1 \
                        and fs[-1] in ["/", "*"]:
                    cal(fs, ns)
                fs.append(s[i])
                pre = i + 1
            else:
                pass

        return ns[-1]

