    def productExceptSelf(self, nums: list) -> list:
        # L 从左向右累乘
        # Ｒ 从右向左累乘
        # 防止越界，像L，R左右各添加 1
        # 对于nums对应的位置 i 的结果值：result = L[i]*R[i+2]
        nl = len(nums)
        L, R = [1 for _ in range(nl + 2)], [1 for _ in range(nl + 2)]
        for i in range(nl):
            L[i + 1] = L[i] * nums[i]
