            app.specter._info["utxorescan"] = 1
            app.specter.utxorescanwallet = wallet.alias
        elif action == "abortrescanutxo":
            app.specter.abortrescanutxo()
            app.specter._info["utxorescan"] = None
            app.specter.utxorescanwallet = None
