from django.views.generic import View
from django.http import HttpResponse, HttpResponseNotFound, HttpResponseServerError, HttpResponseBadRequest
from django.core.cache import cache
from django.db import connection
from django.conf import settings

from . import defaults

import string
import random


class HealthView(View):

    def get(self, request, *args, **kwargs):

        return HttpResponse(status=200)


class CacheHealthView(View):

    def get(self, request, *args, **kwargs):

        if not getattr(settings, 'HEALTH_CHECK_CACHE', defaults.HEALTH_DEFAULTS.get('CHECK_CACHE')):
            # We don't want to check this.  Return 400.
            return HttpResponseBadRequest()

        # Create a random cache key to avoid collision
        cache_key = ''.join(random.choice(string.ascii_letters) for _ in range(100))

        # Set the key in the cache and see if we can pull it out.
        cache.set(cache_key, 'works', 20)

        # If so, return 200
        if cache.get(cache_key) == 'works':
            return HttpResponse(status=200)

        # If not, return 404
        return HttpResponseNotFound()


class DBHealthView(View):

    def get(self, request, *args, **kwargs):

        if not getattr(settings, 'HEALTH_CHECK_DB', defaults.HEALTH_DEFAULTS.get('CHECK_DB')):
            # We don't want to check the DB. Return 400.
            return HttpResponseBadRequest()

        with connection.cursor() as c:

            if connection.vendor == 'postgresql':
                from psycopg2 import OperationalError
                try:
                    c.execute('SELECT 1')
                    result = c.fetchone()
                except OperationalError:
                    return HttpResponseServerError()
            else:
                try:
                    c.execute('SELECT 1')
                    result = c.fetchone()
                except Exception:
                    return HttpResponseServerError()

            return HttpResponse(result, status=200)

'''
题目描述：
给定一个整数数组，如何快速地求出该数组中第k小的数。
输入样例：
arr=[4,0,1,0,2,3] k=3
输出：
1

方法一：排序法。先将数组排序，然后返回下标为[k-1]的元素,O(Nlog2(N))
方法二：部分排序法。改写选择排序，外层循环跑k次，每次都找到右边数组中的最小值。O(k*n)
方法三：类快速排序法。
随机选出当前数组中一个元素，记录其下标为i
若i-low == k-1,则arr[i]即为第k小的数
若i-low > k-1，则递归地在arr[:i]中查找第k小的数
若i-low < k-1,则递归地在arr[i+1:]中找第(k-1)-(i-low)小的数
'''
#方法一实现
def findSmallK(arr,k):
	if arr is None:
		return
	if type(k) != int or len(arr) < k or k <= 0:
		return
	arr = quick_sort(arr)
	return arr[k-1]

def quick_sort(arr):
	if len(arr) <= 1:
		return arr
	L = []
	E = []
	G = []
	import random
	key = random.choice(arr)
	for v in arr:
		if v < key:
			L.append(v)
		elif v == key:
			E.append(v)
		else:
			G.append(v)
	return quick_sort(L) + E + quick_sort(G)

#方法二实现
def findSmallK2(arr,k):
	if arr is None:
		return
	if type(k) != int or len(arr) < k or k<= 0:
		return
	for i in range(k):
		Min = i
		for j in range(i,len(arr)):
			if arr[j] < arr[Min]:
				Min = j
		arr[i],arr[Min] = arr[Min],arr[i]
	return arr[i]

#方法三类快速排序实现
def findSmallK3(arr,k,low,high):
	if arr is None:
		return
	if type(k) != int or len(arr) < k or k<= 0:
		return
	L = []
	E = []
	G = []
	import random
	i = random.choice(range(low,high+1))
	key = arr[i]
	for j in range(len(arr)):
		if j == i:
			continue
		if arr[j] <= key:
			L.append(arr[j])
		else:
			G.append(arr[j])
	if i-low == k-1:
		return arr[i]
	if i-low > k-1: 
		return findSmallK3(L,k,0,i-1)
	print('-')
	return findSmallK3(arr,(k-1)-(i-low),i+1,len(arr)-1) 

if __name__ == '__main__':
	arr = [4,0,1,0,2,3]
	k = 4
	print(findSmallK3(arr,k,0,len(arr)-1))

import time

from ray.rllib.models.action_dist import ActionDistribution
from ray.rllib.models.modelv2 import ModelV2
from ray.rllib.utils.annotations import override
from ray.rllib.utils.framework import try_import_jax, try_import_tfp
from ray.rllib.utils.typing import TensorType, List

jax, flax = try_import_jax()
tfp = try_import_tfp()


class JAXDistribution(ActionDistribution):
    """Wrapper class for JAX distributions."""

    @override(ActionDistribution)
    def __init__(self, inputs: List[TensorType], model: ModelV2):
        super().__init__(inputs, model)
        # Store the last sample here.
        self.last_sample = None
        # Use current time as pseudo-random number generator's seed.
        self.prng_key = jax.random.PRNGKey(seed=int(time.time()))

    @override(ActionDistribution)
    def logp(self, actions: TensorType) -> TensorType:
        return self.dist.log_prob(actions)

    @override(ActionDistribution)
    def entropy(self) -> TensorType:
        return self.dist.entropy()

    @override(ActionDistribution)
    def kl(self, other: ActionDistribution) -> TensorType:
        return self.dist.kl_divergence(other.dist)

    @override(ActionDistribution)
    def sample(self) -> TensorType:
        # Update the state of our PRNG.
        _, self.prng_key = jax.random.split(self.prng_key)
        self.last_sample = jax.random.categorical(self.prng_key, self.inputs)
        return self.last_sample

    @override(ActionDistribution)
    def sampled_action_logp(self) -> TensorType:
        assert self.last_sample is not None
        return self.logp(self.last_sample)


class JAXCategorical(JAXDistribution):
    """Wrapper class for a JAX Categorical distribution."""

    @override(ActionDistribution)
    def __init__(self, inputs, model=None, temperature=1.0):
        if temperature != 1.0:
            assert temperature > 0.0, "Categorical `temperature` must be > 0.0!"
            inputs /= temperature
        super().__init__(inputs, model)
        self.dist = tfp.experimental.substrates.jax.distributions.Categorical(
            logits=self.inputs
        )

    @override(ActionDistribution)
    def deterministic_sample(self):
        self.last_sample = self.inputs.argmax(axis=1)
        return self.last_sample

    @staticmethod
    @override(ActionDistribution)
    def required_model_output_shape(action_space, model_config):
        return action_space.n

from collections import defaultdict, OrderedDict
import random
from colorama import init, Fore
import os
import re

init(autoreset=True)

safe_pattern = re.compile('^[a-z]{9}$')


def extract_words():
    dir_path = os.path.dirname(os.path.realpath(__file__))
    with open(dir_path + '/american-english.txt', 'r') as f:
        raw_data = f.read().split('\n')
        data = list(filter(is_clean, raw_data))
        return data


def is_clean(word):
    return re.search(safe_pattern, word) is not None


def extract_cores(wordlist):
    coremap = defaultdict(list)
    for word in wordlist:
        coremap[word[3:6]].append(word)
    return coremap


all_words = extract_words()
coremap = extract_cores(all_words)


class Wordmonger(object):

    def __init__(self, all_words, coremap):
        self.words = all_words
        self.coremap = coremap
        self.challenge = OrderedDict()

    def answer_count(self, candidate):
        value = self.coremap.get(candidate, None)
        if value is None:
            return 0
        else:
            return len(value)

    def answers(self, candidate):
        return self.coremap.get(candidate, None)

    def generate(self):
        key = random.choice(list(self.coremap.keys()))
        return key
        # return self.coremap[key]

    def check(self, arg):
        return arg in self.coremap[arg[3:6]]

    def show_challenge(self):
        for idx, (key, value) in enumerate(self.challenge.iteritems(), 1):
            if value is not None:
                print(
                    "{idx}:\t {color}{word}".format(
                        **{
                            'idx': idx, 'word': value, 'color': Fore.GREEN
                        }
                    )
                )
            else:
                print(
                    "{idx}:\t ___{core}___".format(
                        **{'idx': idx, 'core': key}
                    )
                )

    def formulate_challenge(self, n=10):
        self.challenge = OrderedDict()
        while n > 0:
            new_core = random.choice(list(self.coremap.keys()))
            if new_core not in list(self.challenge.keys()):
                self.challenge[new_core] = None
                n -= 1

    def claim(self, answer):
        key = answer[3:6]
        if (
            answer in self.coremap[key]
            and key in list(self.challenge.keys())
        ):
            self.challenge[key] = answer
            return True
        else:
            return False


monger = Wordmonger(all_words, coremap)

